const menu=document.querySelector('.menu'),nav=document.querySelector('#navigation'),lang=document.querySelector('.lang');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});lang.addEventListener('click',()=>{const en=document.documentElement.lang==='es';document.documentElement.lang=en?'en':'es';document.querySelectorAll('[data-es]').forEach(el=>el.innerHTML=el.dataset[en?'en':'es']);lang.textContent=en?'ES':'EN';lang.setAttribute('aria-label',en?'Cambiar idioma a español':'Switch language to English');nav.setAttribute('aria-label',en?'Main navigation':'Navegación principal');document.title=en?'ARTI — Entertainment that connects':'ARTI — Entretenimiento que conecta'});
